+      overflow: hidden;
+    }
+
+    header {
+      padding: 32px 32px 10px;
+    }
+
+    h1 {
+      margin: 0 0 10px;
+      font-size: clamp(2rem, 4vw, 3.25rem);
+      letter-spacing: -0.04em;
+    }
+
+    .subtitle {
+      margin: 0;
+      color: var(--muted);
+      line-height: 1.6;
+    }
+
+    .faq {
+      padding: 12px 20px 28px;
+    }
+
+    .example {
+      margin: 12px 0;
+      border: 1px solid rgba(148, 163, 184, 0.14);
+      border-radius: 18px;
+      background: rgba(15, 23, 42, 0.72);
+      overflow: hidden;
+      transition: border-color 180ms ease, transform 180ms ease, background 180ms ease;
+    }
+
+    .example:hover {
+      transform: translateY(-1px);
+      border-color: rgba(245, 158, 11, 0.28);
+      background: rgba(15, 23, 42, 0.88);
+    }
+
+    .question {
+      width: 100%;
+      appearance: none;
+      border: 0;
+      background: transparent;
+      color: inherit;
+      font: inherit;
+      text-align: left;
+      padding: 20px 22px;
+      cursor: pointer;
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 18px;
+    }
+
+    .question span {
+      font-size: 1.05rem;
+      font-weight: 650;
+      line-height: 1.4;
+    }
+
+    .icon {
+      flex: 0 0 auto;
+      width: 34px;
+      height: 34px;
+      border-radius: 999px;
+      display: grid;
+      place-items: center;
+      background: var(--accent-soft);
+      color: #fbbf24;
+      transition: transform 180ms ease, background 180ms ease;
+    }
+
+    .example.open .icon {
+      transform: rotate(45deg);
+      background: rgba(245, 158, 11, 0.18);
+    }
+
+    .details {
+      padding: 0 22px 20px;
+      color: var(--muted);
+      line-height: 1.7;
+      max-width: 70ch;
+    }
+
+    .details[hidden] {
+      display: none;
+    }
+
+    .details p {
+      margin: 0;
+    }
+
+    .details ul {
+      margin: 12px 0 0;
+      padding-left: 20px;
+    }
+
+    @media (max-width: 640px) {
+      header,
+      .faq {
+        padding-left: 18px;
+        padding-right: 18px;
+      }
+
+      .question,
+      .details {
+        padding-left: 18px;
+        padding-right: 18px;
+      }
+
+      .question span {
+        font-size: 1rem;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main class="page">
+    <header>
+      <h1>Cat FAQ</h1>
+      <p class="subtitle">Quick answers to the most common questions about cats, their quirks, and how to keep them happy.</p>
+    </header>
+
+    <section class="faq" aria-label="Frequently asked questions about cats">
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="cat-1">
+          <span>Why do cats sleep so much?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="cat-1" hidden>
+          <p>Cats conserve energy for short bursts of hunting and play. Most adult cats sleep between 12 and 16 hours a day, and kittens or senior cats may sleep even more.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="cat-2">
+          <span>Do cats really like being petted?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="cat-2" hidden>
+          <p>Many do, but they prefer it on their own terms. Most cats enjoy gentle strokes on the cheeks, chin, and head, while belly rubs are often a no-go unless the cat clearly invites them.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="cat-3">
+          <span>Why do cats bring home "gifts"?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="cat-3" hidden>
+          <p>This behavior is usually instinctive. Cats may be sharing prey, practicing hunting skills, or simply treating their humans as part of the pride.</p>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="cat-4">
+          <span>How can I keep an indoor cat entertained?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="cat-4" hidden>
+          <p>Rotate toys, add scratching posts, provide climbing spots, and schedule interactive play sessions. Puzzle feeders and window views also help keep indoor cats mentally engaged.</p>
+        </div>
+      </div>
+    </section>
+  </main>
+
+  <script>
+    document.querySelectorAll(".example").forEach((example) => {
+      const button = example.querySelector(".question");
+      const details = example.querySelector(".details");
+
+      button.addEventListener("click", () => {
+        const isOpen = button.getAttribute("aria-expanded") === "true";
+        button.setAttribute("aria-expanded", String(!isOpen));
+        details.hidden = isOpen;
+        example.classList.toggle("open", !isOpen);
+      });
+    });
+  </script>
+</body>
+</html>
*** End Patch
